CREATE PROCEDURE CreateInventory
    @Name VARCHAR(50),
    @Price MONEY,
    @Quantity INT,
    @NewId INT OUTPUT
AS
BEGIN
    INSERT INTO Inventory (Name, Price, Quantity, AddedOn)
    VALUES (@Name, @Price, @Quantity, GETDATE());

    SET @NewId = SCOPE_IDENTITY();
END
